interface Workbench { loaded: boolean; saved: boolean; name?: string; layout?: string; complete: boolean; dirty: boolean; dirtyBlocks: number[]; blocks: Block[]; diffs: BlockDiff[]; validation: { valid: boolean; errors: string[]; warnings: string[] }; sourceUid?: string; uidLength: number; }
