interface Task { id: string; name: string; status: string; }
interface RecoveryStep { number: number; stage: string; label: string; status: string; message?: string; }
interface RecoveryResult { outcome: "complete" | "partial" | "failed"; steps: RecoveryStep[]; verifiedKeySlots: number; coveredSectors: number; readableSectors: number; totalSectors: number; dumpComplete: boolean; failedStep?: number; failedStage?: string; reason?: string; hardnestedAvailable: boolean; readerRecovered: boolean; }
interface UIDPreview { currentUid: string; newUid: string; bcc: string; oldBlock0: string; newBlock0: string; }
interface UIDPreflight { token?: string; valid: boolean; preview?: UIDPreview; warning?: string; error?: string; }
interface UIDResult { oldUid: string; newUid?: string; oldBlock0: string; newBlock0: string; actualBlock0?: string; backupPath?: string; verified: boolean; }
interface TaskEvent { taskId: string; kind: string; type: "started" | "progress" | "completed" | "cancelled" | "failed"; phase?: string; progress: number; sector?: number; keyType?: string; attempted?: number; found?: number; block?: number; message: string; time: string; workbench?: Workbench; step?: number; totalSteps?: number; stepStatus?: string; indeterminate?: boolean; recovery?: RecoveryResult; uid?: UIDResult; virtualLab?: VirtualLabResult; }
interface Preflight { token?: string; mode: string; valid: boolean; blocks: number[]; trailerBlocks: number[]; skippedBlock0: boolean; warnings: string[]; error?: string; access: Array<{ block: number; sector: number; access: AccessSummary }>; uid?: UIDPreview; }
interface DiagnosticCheck { id: string; name: string; ok: boolean; version?: string; detail?: string; }
interface DiagnosticReport { healthy: boolean; generatedAt: string; build: { version: string; commit: string; buildDate: string; dirty: boolean; goVersion: string; wailsVersion: string; os: string; architecture: string }; libnfc: { available: boolean; version?: string; drivers: string[]; error?: string }; engines: DiagnosticCheck[]; manifest: { found: boolean; verified: boolean; files: number; detail?: string }; currentDevice?: string; supportedReaders: string[]; }
