async function openEditor(block: Block): Promise<void> { if (activeTask) return; try { const editable = (await GetEditableBlock(block.block)) as EditableBlock; editingBlock = editable.block; editorTitle.textContent = editable.kind === "trailer" ? t("editor.trailer_title", { sector: editable.sector, block: editable.block }) : editable.kind === "manufacturer" ? t("editor.manufacturer_title") : t("editor.data_title", { block: editable.block }); hexEditor.value = spacedHex(editable.hex); asciiEditor.value = editableASCIIValue(editable); editorWarning.hidden = !editable.warning; editorWarning.textContent = editable.warning || ""; accessPanel.hidden = editable.kind !== "trailer"; accessPanel.replaceChildren(); if (editable.kind === "trailer") accessPanel.append(text("h3", "访问控制位说明"), renderAccess(editable.access)); editorModal.showModal(); } catch (error) { appendLog(`无法打开编辑器：${String(error)}`, undefined, "error"); } }
async function startTask(starter: () => Promise<unknown>, clearBeforeStart = false): Promise<void> { startingTask = true; rawStreams = { stdout: "", stderr: "" }; rawLogContent.textContent = "尚无外部进程输出"; taskState.textContent = "正在启动"; taskState.dataset.state = "running"; progressBar.classList.add("indeterminate"); progressBar.style.width = "2%"; if (clearBeforeStart) renderWorkbench(emptyWorkbench); updateActions(); try { const task = (await starter()) as Task; if (terminalTaskIDs.delete(task.id)) { activeTask = null; return; } activeTask = task; taskState.textContent = "运行中"; taskState.dataset.state = "running"; progressBar.style.width = "2%"; } catch (error) { appendLog(`无法启动任务：${String(error)}`, undefined, "error"); activeTask = null; taskState.textContent = "启动失败"; taskState.dataset.state = "failed"; progressBar.classList.remove("indeterminate"); progressBar.style.width = "0%"; if (clearBeforeStart) { try { renderWorkbench((await GetWorkbench()) as Workbench); } catch { /* retain the explicit empty state when refresh also fails */ } } } finally { startingTask = false; updateActions(); } }

function uidPreviewElement(preview: UIDPreview): HTMLElement { const box = document.createElement("div"); box.className = "uid-preview-card"; box.append(text("strong", `${preview.currentUid} → ${preview.newUid}`), text("span", `BCC：${preview.bcc}`), text("code", `原 block 0　${preview.oldBlock0}`), text("code", `新 block 0　${preview.newBlock0}`)); return box; }
async function openPreflight(mode: "changes" | "full", writeUid = false, uid = ""): Promise<void> {
  appendLog("正在执行只读预检…");
  try { pendingPreflight = (await PreflightWrite({ mode, writeUid, uid })) as Preflight; preflightContent.replaceChildren(); trailerConfirmRow.hidden = true; restoreUIDConfirmRow.hidden = true; if (!pendingPreflight.valid) { preflightContent.append(text("div", pendingPreflight.error || "预检未通过", "preflight-error")); executeWriteButton.disabled = true; } else { const summary = document.createElement("div"); summary.className = "preflight-summary"; summary.append(text("strong", `计划写入 ${pendingPreflight.blocks.length} 个 block`), text("span", pendingPreflight.blocks.join(", "))); preflightContent.append(summary); if (mode === "changes" && bench.diffs.length) { const diffList = document.createElement("div"); diffList.className = "diff-list"; diffList.append(text("h3", "工作副本差异")); bench.diffs.forEach((diff) => diffList.append(text("p", `Block ${diff.block}：${diff.bytes.map((item) => `${item.offset.toString().padStart(2, "0")} ${item.before}→${item.after}`).join(" · ")}`))); preflightContent.append(diffList); } if (pendingPreflight.uid) preflightContent.append(uidPreviewElement(pendingPreflight.uid)); pendingPreflight.warnings.forEach((warning) => preflightContent.append(text("div", warning, "warning-line"))); pendingPreflight.access.forEach((item) => { const section = document.createElement("section"); section.className = "trailer-access"; section.append(text("h3", `扇区 ${item.sector} · 控制块 ${item.block}`), renderAccess(item.access)); preflightContent.append(section); }); trailerConfirmRow.hidden = !pendingPreflight.trailerBlocks.length; trailerConfirm.checked = false; restoreUIDConfirmRow.hidden = !pendingPreflight.uid; restoreUIDConfirm.value = ""; executeWriteButton.disabled = false; } preflightModal.showModal(); } catch (error) { appendLog(`预检失败：${String(error)}`, undefined, "error"); }
}

