function renderVirtualLabResult(result: VirtualLabResult): void {
  const lines = result.action === "one_click_audit"
    ? [`受限审计：${result.found ? "命中合成测试口令" : "未命中"}`, `尝试次数：${result.attempts} / ${result.maxAttempts}`]
    : [`静态克隆：${result.cloneRejected ? "动态认证已拒绝" : "检测异常"}`, `UID 冲突：${result.uidCollision ? "是" : "否"}`, `静态指纹一致：${result.staticFingerprintMatch ? "是" : "否"}`, `原卡动态认证：${result.originalDynamicAuth ? "通过" : "失败"}`];
  virtualLabResult.replaceChildren(...lines.map((line) => text("span", line)));
}
