el<HTMLButtonElement>("#add-key-button").addEventListener("click", async (event) => { event.preventDefault(); const value = keyInput.value.replace(/\s/g, ""); if (!/^[\da-fA-F]{12}$/.test(value)) { showCatalogReport(t("keys.invalid_format"), "error"); return; } try { renderCatalog((await AddKey(value)) as KeyEntry[]); keyInput.value = ""; showCatalogReport(t("keys.added")); appendLog(t("keys.added")); } catch (error) { showCatalogReport(t("keys.add_failed", { error: String(error) }), "error"); appendLog(t("keys.add_failed", { error: String(error) }), undefined, "error"); } });
el<HTMLButtonElement>("#import-keys-button").addEventListener("click", async (event) => { event.preventDefault(); try { const report = await ImportKeyDictionary(); if (!report.cancelled) { renderCatalog(report.keys as KeyEntry[]); showCatalogReport(`新增 ${report.added} · 重复 ${report.duplicates} · 非法 ${report.issues.length}`); report.issues.slice(0, 8).forEach((issue) => importReport.append(text("span", `第 ${issue.line} 行：${issue.message}`))); appendLog(`字典导入：新增 ${report.added}，重复 ${report.duplicates}，非法 ${report.issues.length}`); } } catch (error) { showCatalogReport(`导入失败：${String(error)}`, "error"); appendLog(`导入失败：${String(error)}`, undefined, "error"); } });
el<HTMLButtonElement>("#export-keys-button").addEventListener("click", async (event) => { event.preventDefault(); try { const result = await ExportKeyDictionary(); if (!result.cancelled) appendLog(`已导出 ${result.count} 个密钥至 ${result.path}`); } catch (error) { appendLog(`导出失败：${String(error)}`, undefined, "error"); } });
loadButton.addEventListener("click", async () => { let discard = false; if (bench.dirty) { discard = window.confirm("当前工作副本有未保存修改。放弃修改并加载其他文件？"); if (!discard) return; } try { renderWorkbench((await LoadDump(discard)) as Workbench); appendLog("Dump 已载入工作台"); } catch (error) { appendLog(`加载失败：${String(error)}`, undefined, "error"); } });
saveButton.addEventListener("click", async () => { try { const result = await SaveDump(); if (!result.cancelled) appendLog(`已保存 ${result.path}${result.sidecar ? ` 与 ${result.sidecar}` : ""}`); } catch (error) { appendLog(`保存失败：${String(error)}`, undefined, "error"); } });
undoButton.addEventListener("click", async () => { try { renderWorkbench((await UndoWorkbench()) as Workbench); } catch (error) { appendLog(`撤销失败：${String(error)}`, undefined, "error"); } });
clearButton.addEventListener("click", async () => { const previous = bench; renderWorkbench(emptyWorkbench); appendLog("正在清空工作区…"); try { renderWorkbench((await ClearWorkbench()) as Workbench); appendLog("工作区已清空", undefined, "success"); } catch (error) { try { renderWorkbench((await GetWorkbench()) as Workbench); } catch { renderWorkbench(previous); } appendLog(`清空失败：${String(error)}`, undefined, "error"); } });
el<HTMLButtonElement>("#apply-hex-button").addEventListener("click", async (event) => { event.preventDefault(); try { renderWorkbench((await EditBlockHex(editingBlock, hexEditor.value)) as Workbench); editorModal.close(); appendLog(`Block ${editingBlock} 已在工作副本中修改`); } catch (error) { appendLog(`Hex 编辑失败：${String(error)}`, undefined, "error"); } });
