migrationButton.addEventListener("click", () => { migrationStatus.textContent = bench.loaded && bench.complete ? t("migration.ready_target") : t("migration.ready_source"); migrationModal.showModal(); });
migrationReadSource.addEventListener("click", () => { if (!card.present) { migrationStatus.textContent = t("migration.no_card"); return; } migrationStatus.textContent = t("migration.reading"); void startTask(() => StartReadCard(true), true); });
migrationWriteTarget.addEventListener("click", () => { if (!bench.loaded || !bench.complete) { migrationStatus.textContent = t("migration.need_source"); return; } migrationModal.close(); restoreWriteUID.checked = false; restoreUIDField.hidden = true; restoreUIDInput.value = ""; restoreOptionsModal.showModal(); });
recoverButton.addEventListener("click", () => recoveryConfirmModal.showModal()); confirmRecoveryButton.addEventListener("click", (event) => { event.preventDefault(); if (!card.present) { recoveryConfirmModal.close(); appendLog("卡片已离开，无法开始自动恢复密钥", undefined, "error"); return; } if (startingTask || activeTask) { recoveryConfirmModal.close(); appendLog("已有任务正在运行，请先完成或取消当前任务", undefined, "error"); return; } cardPrepared = false; recoveryConfirmModal.close(); resetRecoverySteps(); appendLog(bench.dirty ? "已放弃未保存修改，正在启动五阶段自动密钥恢复流程…" : "正在启动五阶段自动密钥恢复流程…"); void startTask(() => StartKeyRecovery({ authorized: true, discardDirty: true }), true); }); readButton.addEventListener("click", () => { let discard = false; if (bench.dirty) { discard = window.confirm("读取卡片会替换当前未保存的工作副本。放弃修改并继续？"); if (!discard) return; } void startTask(() => StartReadCard(discard), true); }); writeChangesButton.addEventListener("click", () => void openPreflight("changes"));
restoreButton.addEventListener("click", () => { restoreWriteUID.checked = false; restoreUIDField.hidden = true; restoreUIDInput.value = bench.uidLength === 4 ? bench.sourceUid || "" : ""; restoreWriteUID.disabled = false; restoreWriteUID.title = "卡型、UID 长度和 sector 0 密钥将在安全预检中检查"; restoreOptionsModal.showModal(); });
restoreWriteUID.addEventListener("change", () => { restoreUIDField.hidden = !restoreWriteUID.checked; if (restoreWriteUID.checked && !restoreUIDInput.value && bench.uidLength === 4) restoreUIDInput.value = bench.sourceUid || ""; });
el<HTMLButtonElement>("#restore-preflight-button").addEventListener("click", (event) => { event.preventDefault(); const writeUid = restoreWriteUID.checked; if (writeUid && !restoreUIDInput.value.trim()) { appendLog("请输入要写入的 4-byte UID", undefined, "error"); return; } restoreOptionsModal.close(); void openPreflight("full", writeUid, restoreUIDInput.value); });
uidWriteButton.addEventListener("click", () => { pendingUIDPreflight = null; uidWriteInput.value = ""; uidWriteConfirm.value = ""; uidWritePreview.replaceChildren(); uidWriteConfirmRow.hidden = true; uidExecuteButton.hidden = true; uidPreflightButton.hidden = false; uidWriteModal.showModal(); });
uidWriteInput.addEventListener("input", () => { pendingUIDPreflight = null; uidWritePreview.replaceChildren(); uidWriteConfirmRow.hidden = true; uidExecuteButton.hidden = true; uidPreflightButton.hidden = false; });
uidPreflightButton.addEventListener("click", async (event) => { event.preventDefault(); uidPreflightButton.disabled = true; uidWritePreview.replaceChildren(text("span", "正在检查卡片与 block 0…")); try { pendingUIDPreflight = (await PreflightUIDWrite(uidWriteInput.value)) as UIDPreflight; uidWritePreview.replaceChildren(); if (!pendingUIDPreflight.valid || !pendingUIDPreflight.preview) { uidWritePreview.append(text("div", pendingUIDPreflight.error || "预检未通过", "preflight-error")); return; } uidWritePreview.append(uidPreviewElement(pendingUIDPreflight.preview)); if (pendingUIDPreflight.warning) uidWritePreview.append(text("div", pendingUIDPreflight.warning, "warning-line")); uidWriteConfirm.value = ""; uidWriteConfirmRow.hidden = false; uidExecuteButton.hidden = false; uidPreflightButton.hidden = true; } catch (error) { uidWritePreview.replaceChildren(text("div", `预检失败：${String(error)}`, "preflight-error")); } finally { uidPreflightButton.disabled = false; } });
uidExecuteButton.addEventListener("click", async (event) => { event.preventDefault(); if (!pendingUIDPreflight?.valid || !pendingUIDPreflight.token) return; uidWriteModal.close(); await startTask(() => StartUIDWrite({ token: pendingUIDPreflight!.token!, confirmation: uidWriteConfirm.value })); pendingUIDPreflight = null; });
cancelButton.addEventListener("click", async () => { if (!activeTask) return; try { await CancelTask(activeTask.id); cancelButton.disabled = true; taskState.textContent = "正在取消"; } catch (error) { appendLog(`取消失败：${String(error)}`, undefined, "error"); } });
rawLogButton.addEventListener("click", () => rawLogModal.showModal());
executeWriteButton.addEventListener("click", async (event) => { event.preventDefault(); if (!pendingPreflight?.valid || !pendingPreflight.token) return; if (pendingPreflight.trailerBlocks.length && !trailerConfirm.checked) { appendLog("必须确认 sector trailer 风险后才能写入", undefined, "error"); return; } if (pendingPreflight.uid && !restoreUIDConfirm.value.trim()) { appendLog("必须再次输入目标 UID 才能写入", undefined, "error"); return; } preflightModal.close(); await startTask(() => StartWrite({ token: pendingPreflight!.token!, confirmTrailers: trailerConfirm.checked, confirmUid: restoreUIDConfirm.value })); pendingPreflight = null; });

EventsOn("nfcx:device-state", (event: DeviceStateEvent) => { const known = devices.findIndex((item) => item.id === event.device.id); if (event.device.connString && known < 0) devices.push(event.device); renderDevices(devices, event.device.id); renderConnection(event.connection); renderCard(event.card); appendLog(`${event.connection.label}${event.connection.detail ? `：${event.connection.detail}` : ""}`, event.time); });
EventsOn("nfcx:card-state", (event: CardEvent) => { cardPrepared = false; renderSectorKeys([]); renderCard(event.type === "appeared" ? event.card : emptyCard); appendLog(event.type === "appeared" ? `检测到卡片 ${event.card.uid}` : `卡片已移除 ${event.card.uid}`, event.time); void GetDashboard().then((dashboard) => renderSectorKeys(dashboard.keys as SectorKey[])); });
EventsOn("nfcx:update", (event: UpdateResult) => renderUpdate(event));
EventsOn("nfcx:sector-keys", (entries: SectorKey[]) => renderSectorKeys(entries)); EventsOn("nfcx:key-catalog", (entries: KeyEntry[]) => { catalog = entries; if (keysModal.open) renderCatalog(entries); }); EventsOn("nfcx:workbench", (snapshot: Workbench) => renderWorkbench(snapshot));
EventsOn("nfcx:task", (event: TaskEvent & { engine?: string; stream?: string; log?: string; recoveryError?: string }) => { if (event.log) appendRawLog(event.engine ?? "external", event.stream ?? "output", event.log, event.time); else if (event.message) { appendLog(event.message, event.time, event.type === "failed" || event.recoveryError ? "error" : event.type === "completed" ? "success" : ""); if (event.type === "started" || event.type === "progress") operationHint.textContent = event.message; } if (event.virtualLab) renderVirtualLabResult(event.virtualLab); if (event.workbench) renderWorkbench(event.workbench); if (event.uid) { const actual = event.uid.actualBlock0 ? `；实际回读 ${event.uid.actualBlock0}` : ""; const backup = event.uid.backupPath ? `；备份 ${event.uid.backupPath}` : ""; appendLog(`UID 写入报告：原 block 0 ${event.uid.oldBlock0}；目标 block 0 ${event.uid.newBlock0}${actual}${backup}`, event.time, event.uid.verified ? "success" : "error"); } updateRecoveryStep(event); if (event.recovery) { pendingRecoveryResult = event.recovery; renderRecoveryResult(event.recovery); } if (event.type === "started" || event.type === "progress") { taskState.textContent = event.step ? `${event.step}/${event.totalSteps || 5} · ${phaseLabel(event.phase).replace(/^\d\/5 · /, "")}` : event.kind === "keyscan" && typeof event.attempted === "number" ? `已尝试 ${event.attempted} · 找到 ${event.found ?? 0}` : phaseLabel(event.phase); taskState.dataset.state = event.phase === "cancelling" ? "cancelling" : "running"; progressBar.classList.toggle("indeterminate", !!event.indeterminate || !event.progress); progressBar.style.width = `${Math.max(2, event.progress || 2)}%`; } else { if (event.kind === "key_recovery") cardPrepared = event.type === "completed" && pendingRecoveryResult?.outcome === "complete" && card.present; if (activeTask?.id === event.taskId) activeTask = null; else terminalTaskIDs.add(event.taskId); taskState.textContent = event.type === "completed" ? t("task.completed") : event.type === "cancelled" ? t("task.cancelled") : t("task.failed"); taskState.dataset.state = event.type; progressBar.classList.remove("indeterminate"); progressBar.style.width = event.type === "completed" ? "100%" : "0%"; updateActions(); if (event.kind === "key_recovery" && pendingRecoveryResult) { renderRecoveryResult(pendingRecoveryResult); if (!recoveryResultModal.open) recoveryResultModal.showModal(); pendingRecoveryResult = null; } if (event.kind === "keyscan" && event.type === "completed") { const verified = sectorKeys.some((entry) => entry.keyAStatus === "verified" || entry.keyBStatus === "verified"); if (!verified) { appendLog(t("keys.scan_none_found"), undefined, "error"); renderCatalog(catalog); keysModal.showModal(); showCatalogReport(t("keys.scan_prompt_input"), "error"); keyInput.focus(); } else { appendLog(t("keys.scan_completed"), undefined, "success"); } } } });

async function boot(): Promise<void> { refreshLanguage(); applyTheme(storedTheme()); try { const [dashboard, workspace, storedKeys, telemetry, updates] = await Promise.all([GetDashboard(), GetWorkbench(), GetKeyCatalog(), GetTelemetrySettings(), GetUpdateStatus()]); recoverButton.title = "Automatically runs common keys, Darkside, Nested, Hardnested (as needed), and read verification"; aboutVersion.textContent = `v${(await GetDiagnostics() as DiagnosticReport).build.version}`; renderDevices(dashboard.devices as Device[], dashboard.selectedDevice); renderConnection(dashboard.connection as Connection); renderCard(dashboard.card as Card); renderSectorKeys(dashboard.keys as SectorKey[]); renderWorkbench(workspace as Workbench); renderCatalog(storedKeys as KeyEntry[]); renderUpdate(updates as UpdateResult); if (!(telemetry as TelemetrySettings).configured) telemetryConsentModal.showModal(); else if ((telemetry as TelemetrySettings).enabled) TrackTelemetry("app_started"); } catch (error) { appendLog(`Initialization failed: ${String(error)}`, undefined, "error"); } try { renderDevices((await RefreshDevices()) as Device[]); } catch (error) { appendLog(`Reader enumeration failed: ${String(error)}`, undefined, "error"); } }
void boot();
